vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { toIsoTimestamp } from "@/types/common";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

function q(t: Tenant, text: string, kinds: ("issue" | "comment" | "project")[], projectId?: string) {
  return searchService.search(t.actors.member, {
    orgId: t.org.id,
    q: text,
    kinds,
    limit: 25,
    cursor: null,
    ...(projectId ? { projectId: projectId as never } : {}),
  });
}

describe("starter plan (no advanced_search)", () => {
  it("treats colons as literal text and searches issues only", async () => {
    const t = await createTenant("scrstarter", "starter");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Release 2: hotfix" }),
    );
    await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: issue.id,
      body: "flaky on staging",
      parentId: null,
      mentionedUserIds: [],
    });

    const hit = await q(t, "Release 2: hotfix", ["issue"]);
    expect(hit.total).toBe(1);
    expect(hit.items[0]).toMatchObject({ kind: "issue", id: issue.id });

    // Asked for comments and projects too: still only issues come back.
    const all = await q(t, "flaky", ["issue", "comment", "project"]);
    expect(all.total).toBe(0);

    const syntax = await q(t, "kind:comment flaky", ["comment"]);
    expect(syntax.total).toBe(0);
  });
});

describe("enterprise plan (advanced_search)", () => {
  let t: Tenant;
  let issueId: string;
  let commentId: string;

  beforeAll(async () => {
    t = await createTenant("scrent", "enterprise");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Deploy notes" }),
    );
    issueId = issue.id;
    const comment = await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: issue.id,
      body: "flaky deploy on staging",
      parentId: null,
      mentionedUserIds: [],
    });
    commentId = comment.id;
  });

  it("honours kind: and in: tokens", async () => {
    const kind = await q(t, "kind:comment flaky", ["issue"]);
    expect(kind.total).toBe(1);
    expect(kind.items[0]).toMatchObject({ kind: "comment", id: commentId });

    const inAlias = await q(t, "in:comments flaky", ["issue"]);
    expect(inAlias.total).toBe(1);
    expect(inAlias.items[0]).toMatchObject({ kind: "comment" });
  });

  it("honours project: and finds comments inside a project", async () => {
    const scoped = await q(t, `project:${t.project.id} deploy`, ["issue", "comment"]);
    expect(scoped.items.map((h) => h.kind).sort()).toEqual(["comment", "issue"]);

    const commentsOnly = await q(t, "flaky", ["comment"], t.project.id);
    expect(commentsOnly.total).toBe(1);
    expect(commentsOnly.items[0]).toMatchObject({ id: commentId });
  });

  it("matches % and _ literally", async () => {
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Coverage 100% done" }),
    );
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Coverage 1000 done" }),
    );
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "snake case naming" }),
    );
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "snake_case naming" }),
    );

    const pct = await q(t, "100%", ["issue"]);
    expect(pct.items.map((h) => h.title)).toEqual(["Coverage 100% done"]);

    const underscore = await q(t, "snake_case", ["issue"]);
    expect(underscore.items.map((h) => h.title)).toEqual(["snake_case naming"]);
  });

  it("re-indexes an edited comment under its new body", async () => {
    const comment = await commentService.updateComment(t.actors.member, {
      orgId: t.org.id,
      commentId: commentId as never,
      body: "zebra on staging",
    });
    expect(comment.body).toBe("zebra on staging");

    expect((await q(t, "zebra", ["comment"])).total).toBe(1);
    expect((await q(t, "flaky", ["comment"])).total).toBe(0);
  });

  it("reindex requests cover comments, projects and archived issues", async () => {
    // Drop each subject from the index, then ask for a reindex.
    await searchRepo.deleteSearchDocument(t.org.id, "comment", commentId as never);
    expect((await q(t, "zebra", ["comment"])).total).toBe(0);
    await emit("search.reindex_requested", {
      orgId: t.org.id,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      subjectKind: "comment",
      subjectId: commentId,
    });
    expect((await q(t, "zebra", ["comment"])).total).toBe(1);

    await searchRepo.deleteSearchDocument(t.org.id, "project", t.project.id);
    expect((await q(t, t.project.name, ["project"])).total).toBe(0);
    await emit("search.reindex_requested", {
      orgId: t.org.id,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      subjectKind: "project",
      subjectId: t.project.id,
    });
    expect((await q(t, t.project.name, ["project"])).total).toBe(1);

    await issueService.archiveIssue(t.actors.member, t.org.id, issueId as never);
    await emit("search.reindex_requested", {
      orgId: t.org.id,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      subjectKind: "issue",
      subjectId: issueId,
    });
    expect((await q(t, "Deploy notes", ["issue"])).total).toBe(0);
  });

  it("the rebuild job re-indexes comments under their issue's project", async () => {
    await searchRepo.deleteSearchDocument(t.org.id, "comment", commentId as never);
    const result = await runSearchReindexJob(t.org.id);
    expect(result.failed).toBe(0);
    const scoped = await q(t, "zebra", ["comment"], t.project.id);
    expect(scoped.total).toBe(1);
  });
});

